-- Import bundled practices into the admin catalog without replacing curated rows.
INSERT INTO meditation_library_items
  (id,kind,section,title_en,title_hi,description_en,description_hi,preparation_en,preparation_hi,duration_seconds,steps,repeat,published,sort_order,updated_at)
SELECT seed.id::uuid, seed.kind, seed.section, seed.title_en, seed.title_hi, seed.description_en, seed.description_hi, seed.preparation_en, seed.preparation_hi, seed.duration_seconds, seed.steps, seed.repeat, seed.published, seed.sort_order, seed.updated_at
FROM (VALUES
('8e0bc1a0-6ce8-4000-8000-000000000101','practice','rest','Evening wind-down','','5 minutes · Ease into a quieter evening','','Sit or lie somewhere comfortable. Let your eyes stay open or softly closed. There is no need to fall asleep.','',300,'[{"title_en":"Settle into support","title_hi":"","instruction_en":"Notice where your body meets the bed or chair. Adjust anything that feels uncomfortable.","instruction_hi":"","seconds":60},{"title_en":"Let the day rest","title_hi":"","instruction_en":"Notice a thought about today. You do not need to solve it now. Let your attention return to the support beneath you.","instruction_hi":"","seconds":60},{"title_en":"Soften your hands","title_hi":"","instruction_en":"Let your fingers rest. Notice your jaw and shoulders, and allow them to find a comfortable position.","instruction_hi":"","seconds":60},{"title_en":"Follow a natural breath","title_hi":"","instruction_en":"Notice your breathing as it is. Let each breath arrive and leave without a count.","instruction_hi":"","seconds":90},{"title_en":"Stay or return","title_hi":"","instruction_en":"Take a moment to notice how you feel. Rest here or move gently when you are ready.","instruction_hi":"","seconds":30}]'::jsonb,1,true,20,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000102','practice','breathing','One-minute pause','एक मिनट का विराम','Notice one breath and come back to the room.','एक साँस पर ध्यान दें और फिर आसपास की ओर ध्यान लौटाएँ।','Sit or stand somewhere you can pause safely. Let your breathing stay natural.','ऐसी जगह बैठें या खड़े हों जहाँ आराम से रुक सकें। स्वाभाविक रूप से साँस लें।',60,'[{"title_en":"Feel your feet","title_hi":"अपने पैरों को महसूस करें","instruction_en":"Notice where your feet meet the floor. Let your hands rest.","instruction_hi":"महसूस करें कि पैर ज़मीन को कहाँ छू रहे हैं। हाथों को आराम दें।","seconds":20},{"title_en":"Follow one breath","title_hi":"एक साँस पर ध्यान दें","instruction_en":"Notice one breath coming in and going out without changing it.","instruction_hi":"बिना बदलने की कोशिश किए एक साँस को आते और जाते महसूस करें।","seconds":20},{"title_en":"Look around","title_hi":"","instruction_en":"Let your attention return to the room and choose what to do next.","instruction_hi":"ध्यान फिर से कमरे की ओर लाएँ और तय करें कि आगे क्या करना है।","seconds":20}]'::jsonb,1,true,21,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000103','practice','focus','Focus with sound','ध्वनि के साथ एकाग्रता','Bring your attention back to the sounds around you.','अपना ध्यान आसपास की आवाज़ों पर लौटाएँ।','Sit somewhere comfortable. If sound is distracting or hard to hear, use a visual detail instead.','आरामदायक जगह बैठें। आवाज़ ध्यान भटकाए या सुनाई न दे तो किसी दिखने वाली चीज़ पर ध्यान दें।',120,'[{"title_en":"Settle in","title_hi":"","instruction_en":"Notice how the chair or floor supports you.","instruction_hi":"कुर्सी या ज़मीन का सहारा महसूस करें।","seconds":30},{"title_en":"Notice a sound","title_hi":"एक आवाज़ पर ध्यान दें","instruction_en":"Pick one sound nearby. Notice it without needing to name it.","instruction_hi":"पास की एक आवाज़ चुनें। उसे नाम दिए बिना सुनें।","seconds":45},{"title_en":"Return gently","title_hi":"","instruction_en":"When your attention wanders, return to the sound or visual detail you chose.","instruction_hi":"ध्यान भटके तो चुनी हुई आवाज़ या चीज़ पर वापस ध्यान दें।","seconds":45}]'::jsonb,1,true,22,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000104','practice','rest','Pause with kindness','अपने प्रति दयालुता का विराम','Take a few minutes to speak to yourself with care.','कुछ मिनट अपने आप से नरमी से बात करें।','Choose a comfortable seat. Use your own words if the suggested phrase does not fit.','आराम से बैठें। सुझाए गए वाक्य की जगह चाहें तो अपने शब्द चुनें।',150,'[{"title_en":"Settle in","title_hi":"","instruction_en":"Let your hands rest and notice one natural breath.","instruction_hi":"हाथों को आराम दें और एक स्वाभाविक साँस महसूस करें।","seconds":30},{"title_en":"Offer a kind phrase","title_hi":"खुद से कुछ नरम शब्द कहें","instruction_en":"Try saying quietly to yourself: I can take this one moment at a time.","instruction_hi":"मन में धीरे से कहें कि एक बार में एक पल पर ध्यान देना काफ़ी है।","seconds":60},{"title_en":"Make room for a pause","title_hi":"थोड़ा विराम लें","instruction_en":"Let the phrase go. Notice how you are sitting before you return to your day.","instruction_hi":"वाक्य को जाने दें। अपने काम पर लौटने से पहले महसूस करें कि आप कैसे बैठे हैं।","seconds":60}]'::jsonb,1,true,23,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000105','practice','rest','Release the day','दिन को विदा दें','Close the evening with a quiet, seated reflection.','बैठकर शांत चिंतन के साथ शाम पूरी करें।','Sit somewhere comfortable. Let your eyes stay open or softly closed.','आरामदायक जगह बैठें। आँखें खुली रखें या हल्के से बंद करें।',180,'[{"title_en":"Notice your surroundings","title_hi":"अपने आसपास पर ध्यान दें","instruction_en":"Pick one detail in the room and let your attention settle there.","instruction_hi":"कमरे में कोई एक चीज़ चुनें और वहाँ अपना ध्यान टिकने दें।","seconds":30},{"title_en":"Recall one moment","title_hi":"एक पल याद करें","instruction_en":"Think of one ordinary moment from today. You can also stay with your breath.","instruction_hi":"आज का कोई साधारण पल याद करें। चाहें तो अपनी साँस पर ध्यान दें।","seconds":60},{"title_en":"Let the moment pass","title_hi":"उस पल को जाने दें","instruction_en":"Let the memory go and notice where your body is supported.","instruction_hi":"याद को जाने दें और महसूस करें कि शरीर को कहाँ सहारा मिल रहा है।","seconds":60},{"title_en":"Rest here","title_hi":"यहाँ आराम करें","instruction_en":"Take your time. When you are ready, move gently and continue your evening.","instruction_hi":"अपना समय लें। तैयार होने पर धीरे से हिलें और अपनी शाम जारी रखें।","seconds":30}]'::jsonb,1,true,24,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000106','practice','yoga','Seated yoga reset','बैठकर योग का छोटा विराम','A chair-based practice with small, unhurried movements.','कुर्सी पर बैठकर हल्की और धीमी हरकतों का अभ्यास।','Sit on a sturdy chair with both feet on the floor. Keep the movements small and comfortable, and skip any step you prefer.','मज़बूत कुर्सी पर दोनों पैर ज़मीन पर रखकर बैठें। हल्की और सहज हरकतें करें। चाहें तो कोई भी चरण छोड़ दें।',150,'[{"title_en":"Settle in","title_hi":"","instruction_en":"Rest your hands on your thighs and notice the support of the chair.","instruction_hi":"हाथ जाँघों पर रखें और कुर्सी का सहारा महसूस करें।","seconds":30},{"title_en":"Soften your shoulders","title_hi":"कंधों को ढीला छोड़ें","instruction_en":"Gently lift your shoulders, then let them settle. Repeat at your own pace or stay still.","instruction_hi":"कंधों को धीरे से ऊपर उठाएँ और फिर छोड़ दें। अपनी गति से दोहराएँ या स्थिर रहें।","seconds":45},{"title_en":"Reach and return","title_hi":"हाथ आगे बढ़ाएँ और वापस लाएँ","instruction_en":"Reach one hand forward within a comfortable range, then bring it back. Try the other side if you like.","instruction_hi":"एक हाथ आराम से आगे बढ़ाएँ और फिर वापस लाएँ। चाहें तो दूसरे हाथ से करें।","seconds":45},{"title_en":"Rest here","title_hi":"यहाँ आराम करें","instruction_en":"Bring both hands back to your thighs and let your breathing settle naturally.","instruction_hi":"दोनों हाथ फिर जाँघों पर रखें और स्वाभाविक रूप से साँस लें।","seconds":30}]'::jsonb,1,true,25,date_trunc('milliseconds',now())),
('8e0bc1a0-6ce8-4000-8000-000000000107','practice','yoga','Gentle evening yoga','शाम का हल्का योग','Seated stretches followed by a quiet pause.','बैठकर हल्का खिंचाव और फिर शांत विराम।','Sit comfortably with both feet supported. Move only as far as feels easy, and breathe naturally throughout.','दोनों पैरों को सहारा देकर आराम से बैठें। उतना ही हिलें जितना सहज लगे और स्वाभाविक रूप से साँस लें।',180,'[{"title_en":"Find your seat","title_hi":"आराम से बैठें","instruction_en":"Sit upright without stiffening. Rest your hands loosely on your thighs.","instruction_hi":"बिना अकड़े सीधे बैठें। हाथ जाँघों पर ढीले रखें।","seconds":30},{"title_en":"Open and close your hands","title_hi":"हाथ खोलें और ढीले छोड़ें","instruction_en":"Slowly spread your fingers and relax them. Let your shoulders stay easy.","instruction_hi":"उँगलियाँ धीरे से फैलाएँ और फिर ढीली छोड़ें। कंधों को आराम दें।","seconds":45},{"title_en":"Lengthen gently","title_hi":"हल्का-सा सीधे बैठें","instruction_en":"Imagine the crown of your head lifting slightly. Relax and return to your usual posture.","instruction_hi":"कल्पना करें कि सिर का ऊपरी हिस्सा थोड़ा ऊपर उठ रहा है। ढीले होकर अपनी सामान्य मुद्रा में लौटें।","seconds":45},{"title_en":"Finish with stillness","title_hi":"शांति के साथ पूरा करें","instruction_en":"Stay seated and notice your natural breathing for a moment.","instruction_hi":"बैठे रहें और कुछ समय अपनी स्वाभाविक साँस पर ध्यान दें।","seconds":60}]'::jsonb,1,true,26,date_trunc('milliseconds',now()))
) AS seed(id,kind,section,title_en,title_hi,description_en,description_hi,preparation_en,preparation_hi,duration_seconds,steps,repeat,published,sort_order,updated_at)
WHERE NOT EXISTS (SELECT 1 FROM meditation_library_items existing WHERE lower(existing.title_en) = lower(seed.title_en) AND existing.kind = 'practice')
ON CONFLICT (id) DO NOTHING;
